def source(n, title, authors, year, url, source_type, access, locator, scope_limit, evidence_lineage):
    return dict(id=f"ANC-S{n:02}", title=title, authors=authors, year=year, url=url,
                source_type=source_type, access=access, locator=locator,
                scope_limit=scope_limit, accessed=ACCESSED, evidence_lineage=evidence_lineage)


