def ref(n, locator, supports):
    return dict(source_id=f"ANC-S{n:02}", locator=locator, supports=supports)


def desc(reason):
    return dict(status="descriptive-only", reason=reason)


def test(chain, rival, observation, found, ambiguity, timing="emerged during research", status="underdetermined"):
    return dict(status=status, mechanism_chain=chain, strongest_rival=rival,
                discriminating_observation=observation, evidence_sought_found=found,
                remaining_ambiguity=ambiguity, hypothesis_timing=timing)


def claim(n, case_nums, statement, evidence_type, confidence, causal_status, refs, counterevidence, limits, test_record):
    return dict(id=f"ANC-K{n:02}", case_ids=[f"ANC-C{x:02}" for x in case_nums], statement=statement,
                evidence_type=evidence_type, confidence=confidence, causal_status=causal_status,
                sources=refs, counterevidence=counterevidence, inference_limits=limits, test=test_record)


